import subprocess
import sys


def test_condefects_0():
    proc = subprocess.run(
        [sys.executable, "buggy.py"],
        input='4\n1 1 1\n1 2 1\n2 3 1\n3 3 1\n',
        capture_output=True,
        text=True,
        timeout=10,
    )
    expected = '2\n1\n2\n'
    actual = proc.stdout.strip()
    assert actual == expected.strip(), (
        f"Expected {expected.strip()!r}, got {actual!r}"
    )


